def transform(grid):
    # Fill the cells between inward-facing diagonal boundaries with color 2.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v != 0]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out
